<script setup lang="ts">
import {computed,onScopeDispose,ref,shallowRef,watch} from 'vue'
import {ApiError,IdentityChanged,errorMessage,identityEpoch,onIdentityChange} from '@/core/http'
import {can,currentProject,projectId,session} from '@/core/session'
import {formatTime} from '@/core/time'
import {typeDeviceUuid} from '../device-types/type-devices-api'
import {dataBytes,dataHex,dataFromBase64} from './data-stream-runtime-api'
import type {MqttDataSession} from './mqtt-data-runtime-api'
import {dataStreamParameterNames,dataStreamTemplate} from '../device-types/data-stream-publication-api'
import {mqttDownlinkTransport,prepareMqttDownlink,type MqttDownlink,type MqttDownlinkIntent,type MqttDownlinkTransport} from './mqtt-data-downlink-api'
const props=withDefaults(defineProps<{deviceId:string;pin?:MqttDataSession;disabled?:boolean;transport?:MqttDownlinkTransport}>(),{disabled:false,transport:()=>mqttDownlinkTransport})
const emit=defineEmits<{locked:[value:boolean];changed:[]}>(),roles=['OWNER','ADMIN','OPERATOR','VIEWER']
const member=computed(()=>session.ready&&!session.transitioning&&!!session.user?.accountId&&typeDeviceUuid.test(projectId.value)&&typeDeviceUuid.test(props.deviceId)&&can('device:read')&&currentProject.value?.id===projectId.value&&roles.includes(session.user.projectRole||'')&&roles.includes(currentProject.value.myRole||'')),denied=ref(false),readable=computed(()=>member.value&&!denied.value)
const writable=computed(()=>readable.value&&currentProject.value?.status==='ACTIVE'&&can('device:update')&&can('device:control')&&['OWNER','ADMIN'].includes(session.user?.projectRole||'')&&['OWNER','ADMIN'].includes(currentProject.value?.myRole||''))
const shown=ref(false),busy=ref(false),unknown=ref(false),mode=ref<'HEX'|'UTF8'>('HEX'),raw=ref(''),identifier=ref(''),lifetime=ref(60),error=ref(''),notice=ref(''),intent=shallowRef<MqttDownlinkIntent>(),receipt=shallowRef<MqttDownlink>()
const params=ref<Record<string,string>>({}),selectedStream=computed(()=>props.pin?.streams.find(row=>row.identifier===identifier.value)),parameterNames=computed(()=>selectedStream.value?dataStreamParameterNames(selectedStream.value):[])
const locked=computed(()=>shown.value||busy.value||unknown.value),local=computed(()=>{try{const bytes=dataBytes(raw.value,mode.value);if(!bytes.length)throw new Error('请输入至少1个原字节');return{bytes,hex:dataHex(bytes),error:''}}catch(cause){return{bytes:undefined,hex:'',error:errorMessage(cause)}}})
const names:Record<string,string>={PREPARED:'已准备，发送尚未确认',SENDING:'发布结果待核对',BROKER_ACCEPTED:'Broker已接收',REJECTED:'发布被拒绝',EXPIRED:'已过期，未发布',UNKNOWN:'发布结果未知'}
let generation=0,alive=true,controller:AbortController|undefined
function capture(){return{generation,epoch:identityEpoch(),project:projectId.value,device:props.deviceId,actor:session.user?.accountId}}
function current(value:ReturnType<typeof capture>){return alive&&readable.value&&generation===value.generation&&identityEpoch()===value.epoch&&projectId.value===value.project&&props.deviceId===value.device&&session.user?.accountId===value.actor}
function clear(){generation++;controller?.abort();shown.value=false;busy.value=false;unknown.value=false;intent.value=undefined;receipt.value=undefined;raw.value='';identifier.value='';error.value='';notice.value='';mode.value='HEX';lifetime.value=60;params.value={}}
function start(){if(!writable.value||props.disabled||locked.value||!props.pin?.available)return;intent.value=undefined;receipt.value=undefined;raw.value='';error.value='';notice.value='';identifier.value=props.pin.streams[0]?.identifier||'';params.value=Object.fromEntries(parameterNames.value.map(name=>[name,'']));shown.value=true}
function close(){if(busy.value)return;shown.value=false;if(!unknown.value){intent.value=undefined;raw.value='';error.value=''}}
async function review(){if(!writable.value||props.disabled||busy.value||unknown.value||!shown.value||!props.pin||!local.value.bytes)return;const state=capture(),pin=props.pin;busy.value=true;error.value='';try{const value=await prepareMqttDownlink(state.project,state.device,pin,identifier.value,local.value.bytes,lifetime.value,selectedStream.value&&dataStreamTemplate(selectedStream.value)?params.value:undefined);if(current(state)&&props.pin===pin)intent.value=value}catch(cause){if(current(state))error.value=errorMessage(cause)}finally{if(current(state))busy.value=false}}
function complete(value:MqttDownlink){if(receipt.value&&value.messageId!==receipt.value.messageId)throw new Error('原键返回了另一条下发原件');receipt.value=value;unknown.value=['PREPARED','SENDING','UNKNOWN'].includes(value.state);shown.value=false;notice.value=unknown.value?'原件已取得，发布结果仍未确定；只读取原件，不会重发。':'下发结果已取得；Broker接收与设备接收、执行分别判断。';emit('changed')}
async function submit(){const original=intent.value;if(!original||!writable.value||props.disabled||busy.value||unknown.value||!shown.value)return;const state=capture();controller=new AbortController();busy.value=true;unknown.value=true;error.value='';try{const result=await props.transport.create(original,controller.signal);if(current(state)&&intent.value===original)complete(result)}catch(cause){if(current(state)&&!(cause instanceof IdentityChanged)){error.value=errorMessage(cause);if(cause instanceof ApiError&&!cause.outcomeUnknown&&cause.code!==10014&&[400,401,403,404,413,422,429].includes(cause.status)){unknown.value=false;intent.value=undefined}}}finally{if(current(state))busy.value=false}}
async function recover(){const original=intent.value;if(!original||!readable.value||busy.value)return;const state=capture();controller=new AbortController();busy.value=true;error.value='';try{const result=await props.transport.original(original,controller.signal);if(current(state)&&intent.value===original)complete(result)}catch(cause){if(current(state)&&!(cause instanceof IdentityChanged)){if(cause instanceof ApiError&&[401,403].includes(cause.status)){clear();denied.value=true}else error.value=cause instanceof ApiError&&cause.status===404?'尚未取得同次原件，结果仍未知；保留原键，不会再次提交。':errorMessage(cause)}}finally{if(current(state))busy.value=false}}
watch(identifier,()=>{if(!busy.value&&!unknown.value)params.value=Object.fromEntries(parameterNames.value.map(name=>[name,'']))},{flush:'sync'})
watch(params,()=>{if(!busy.value&&!unknown.value)intent.value=undefined},{deep:true,flush:'sync'})
watch([raw,mode,identifier,lifetime,()=>props.pin],()=>{if(!busy.value&&!unknown.value)intent.value=undefined},{flush:'sync'})
watch(locked,value=>emit('locked',value),{immediate:true,flush:'sync'})
watch([()=>props.deviceId,()=>projectId.value,()=>session.user?.accountId,member,()=>props.transport],()=>{clear();denied.value=false},{flush:'sync'})
const dispose=onIdentityChange(clear);onScopeDispose(()=>{alive=false;clear();dispose()})
</script>
<template><section v-if="member" class="mqtt-data-downlinks">
 <p v-if="denied" role="alert">下发原件读取权限已失效，已清除本次原文。</p><template v-else>
 <el-button v-if="writable" type="primary" :disabled="disabled||locked||!pin?.available" @click="start">下发MQTT数据</el-button>
 <p v-if="notice" role="status">{{notice}}</p><p v-if="error" role="alert">{{error}}</p>
 <p v-if="unknown" role="alert">保留本次原键与原字节，仅核对原结果。<el-button :disabled="busy" :loading="busy" @click="recover">核对MQTT下发结果</el-button></p>
 <section v-if="receipt" class="mqtt-downlink-receipt"><h3>本次下发</h3><p>{{receipt.messageId}} · {{names[receipt.state]}}</p><p>流 {{receipt.streamIdentifier}} / {{receipt.format}} · {{receipt.payloadBytes}} 原字节；有效至 {{formatTime(receipt.expiresAt)}}。</p><p>Broker接收不表示设备接收或执行；没有设备应答时不显示设备执行成功。</p><p>实际Topic：<code>{{receipt.topic}}</code></p><p v-if="receipt.params">Topic参数：{{JSON.stringify(receipt.params)}}</p><p>原字节 SHA-256：<code>{{receipt.rawDigest}}</code></p><p v-if="receipt.payloadBase64===null">原文已按保留策略到期；保留原件头及摘要。</p><pre v-else aria-label="MQTT下发原件HEX">{{dataHex(dataFromBase64(receipt.payloadBase64))}}</pre><el-button :disabled="busy" @click="recover">读取本次MQTT下发原件</el-button></section>
 <el-dialog :model-value="shown" title="下发MQTT数据" width="min(680px,94vw)" :close-on-click-modal="false" :close-on-press-escape="!busy" :before-close="(done:()=>void)=>{if(!busy){close();done()}}">
  <p>选择当前连接固定的数据流。一次发布原字节，结果未知时仅核对原件。</p>
  <el-select v-model="identifier" aria-label="MQTT下发数据流" :disabled="disabled||busy||unknown||!writable"><el-option v-for="stream in pin?.streams||[]" :key="stream.identifier" :value="stream.identifier" :label="`${stream.name} (${stream.identifier}) / ${stream.format}`"/></el-select>
  <el-form v-if="parameterNames.length" label-position="top"><p>填写当前固定目标Topic的全部参数；参数不会自动选取其它设备。</p><el-form-item v-for="name in parameterNames" :key="name" :label="name" required><el-input v-model="params[name]" :aria-label="'下发Topic参数 '+name" maxlength="64" :disabled="disabled||busy||unknown||!writable"/></el-form-item><p>每项为1至64位字母、数字、下划线或横线。</p></el-form>
  <el-select v-model="mode" aria-label="MQTT下发输入编码" :disabled="disabled||busy||unknown||!writable"><el-option label="HEX原字节" value="HEX"/><el-option label="UTF-8文本" value="UTF8"/></el-select>
  <el-input v-model="raw" type="textarea" :rows="6" aria-label="MQTT下发原文" :disabled="disabled||busy||unknown||!writable"/><p>有效秒数</p><el-input-number v-model="lifetime" aria-label="MQTT下发有效秒数" :min="1" :max="60" :step="1" :precision="0" :disabled="disabled||busy||unknown||!writable"/>
  <p v-if="local.error" role="alert">{{local.error}}</p><p v-else>{{local.bytes!.length}} 原字节。</p><template v-if="intent"><p>原键：<code>{{intent.key}}</code></p><p>目标Topic：<code>{{intent.expectedTopicSuffix}}</code></p><p v-if="intent.body.params">固定参数：{{JSON.stringify(intent.body.params)}}</p><pre aria-label="MQTT下发确认HEX">{{local.hex}}</pre></template><p v-if="error" role="alert">{{error}}</p>
  <template #footer><el-button :disabled="busy" @click="close">{{unknown?'关闭并保留原请求':'取消'}}</el-button><el-button v-if="!intent&&!unknown" :disabled="disabled||busy||!writable||!!local.error" @click="review">预览MQTT下发</el-button><el-button v-if="intent&&!unknown" type="primary" :loading="busy" :disabled="disabled||busy||!writable" @click="submit">确认一次下发</el-button><el-button v-if="unknown" :loading="busy" :disabled="busy" @click="recover">核对MQTT下发结果</el-button></template>
 </el-dialog></template>
</section></template>
<style scoped>.mqtt-data-downlinks{margin:12px 0;font-size:13px;line-height:22px}.mqtt-data-downlinks .el-select{margin:0 8px 10px 0;width:min(100%,300px)}.mqtt-data-downlinks pre{max-height:280px;overflow:auto;white-space:pre-wrap;overflow-wrap:anywhere;background:var(--tl-bg-base);padding:10px}.mqtt-data-downlinks [role=alert]{color:var(--el-color-danger)}.mqtt-data-downlinks p,.mqtt-data-downlinks code{overflow-wrap:anywhere}.mqtt-downlink-receipt{margin-top:12px;border:1px solid var(--tl-border);padding:12px}</style>
